doc = d.get('document', {})
elements = doc.get('elements', [])

# Check for image or data on page 19
for e in elements:
    page_id = e['bbox'][0]['page_id']
    if page_id == 19:
        print(f'ID: {e[\"id\"]}, Type: {e[\"type\"]}')
